//! The generator of `vm_diff` reaches the instructions it is meant to
//! compare: every one of them shows up in a few hundred programs.

use lapin_fuzz::input::Input;
use lapin_metal::op::*;

/// The instructions of a generated bytecode, function by function.
fn instructions(bc: &[u8]) -> Vec<u8> {
    let int = |o: usize| u32::from_le_bytes(bc[o..o + 4].try_into().unwrap()) as usize;
    let code_at = int(0);
    let len = int(code_at);
    let code = &bc[code_at + 4..code_at + 4 + len];
    let nfun = u16::from_le_bytes(bc[code_at + 4 + len..][..2].try_into().unwrap()) as usize;
    let table = code_at + 4 + len + 2;
    let mut starts: Vec<usize> = (0..nfun).map(|f| int(table + 4 * f)).collect();
    starts.push(len);
    let one = [
        INTB, GETLOCALB, MKTABB, DEFTABB, FETCHB, GETGLOBALB, SETLOCALB, SETSTRUCTB, CALLRB,
    ];
    let mut ops = Vec::new();
    for w in starts.windows(2) {
        // After each function's header: arguments, locals.
        let mut pc = w[0] + 3;
        while pc < w[1] {
            let op = code[pc] as i32;
            ops.push(code[pc]);
            pc += 1 + match op {
                INT => 4,
                GOTO | ELSE => 2,
                o if one.contains(&o) => 1,
                _ => 0,
            };
        }
    }
    ops
}

#[test]
fn the_generator_reaches_every_instruction_it_compares() {
    #[rustfmt::skip]
    let wanted = [
        EXEC, CALL, CALLR, CALLRB, FIXARG, FIRST, HD, TL, DUP, SETSTRUCT, SETSTRUCTB, STORE,
        SETGLOBAL, GETGLOBAL, GETGLOBALB, GETLOCAL, SETLOCAL, SETLOCAL2, MKTAB, MKTABB, DEFTAB,
        DEFTABB, TABNEW, FETCH, FETCHB, TABLEN, STRCATLIST, LISTSWITCH, LISTSWITCHSTR, TIME,
        TIME_MS, ENVGET, ENVSET, GC, RFIDGET, RFIDGETLIST, RFIDREAD, RFIDWRITE, NETSEND, NETCHK,
        NETSTATE, NETRSSI, NETMAC, GOTO, ELSE,
    ];
    let mut seen = [false; 256];
    let mut seed = 0x2545_F491u32;
    for _ in 0..400 {
        let data: Vec<u8> = (0..3000)
            .map(|_| {
                seed ^= seed << 13;
                seed ^= seed >> 17;
                seed ^= seed << 5;
                seed as u8
            })
            .collect();
        let bc = lapin_fuzz::program::program(&mut Input::new(&data));
        for op in instructions(&bc) {
            seen[op as usize] = true;
        }
    }
    let missing: Vec<_> = wanted.iter().filter(|&&o| !seen[o as usize]).collect();
    assert!(missing.is_empty(), "never generated: {missing:?}");
}

/// Generated programs on both machines (`--features cref`): the same
/// everywhere, and they do reach the board's success paths: frames
/// sent, tag blocks read.
#[cfg(feature = "cref")]
#[test]
fn generated_programs_run_the_same_on_both_machines() {
    use lapin_metal_cref::{World, run_both};
    let mut seed = 0x9E37_79B9u32;
    let (mut sent, mut read, mut lines) = (0, 0, 0);
    for k in 0..200 {
        let data: Vec<u8> = (0..3000)
            .map(|_| {
                seed ^= seed << 13;
                seed ^= seed >> 17;
                seed ^= seed << 5;
                seed as u8
            })
            .collect();
        let bc = lapin_fuzz::program::program(&mut Input::new(&data));
        let c = run_both(
            || {
                let mut w = World::new(Vec::new());
                w.now_ms = k * 37;
                w
            },
            &bc,
            1,
        );
        let count = |what: &str| c.world.log.iter().filter(|l| l.starts_with(what)).count();
        sent += count("send");
        read += count("rfid read");
        lines += c.world.console.iter().filter(|b| **b == b'\n').count();
    }
    println!("{sent} frames sent, {read} blocks read, {lines} lines printed");
    assert!(sent > 0 && read > 0 && lines > 1000);
}
